package com.learnagent.task; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/tasks") public class TaskController {private final TaskService service;public TaskController(TaskService service){this.service=service;}@PostMapping public ResponseEntity<TaskDtos.Response> create(@Valid @RequestBody TaskDtos.Request r){return ResponseEntity.status(HttpStatus.CREATED).body(TaskDtos.Response.from(service.create(r)));}@GetMapping public List<TaskDtos.Response> list(@RequestParam(required=false)UUID courseId,@RequestParam(required=false)TaskStatus status){return service.list(courseId,status).stream().map(TaskDtos.Response::from).toList();}@GetMapping("/{id}")public TaskDtos.Response get(@PathVariable UUID id){return TaskDtos.Response.from(service.get(id));}@PutMapping("/{id}")public TaskDtos.Response update(@PathVariable UUID id,@Valid @RequestBody TaskDtos.Request r){return TaskDtos.Response.from(service.update(id,r));}@PostMapping("/{id}/complete")public TaskDtos.Response complete(@PathVariable UUID id){return TaskDtos.Response.from(service.complete(id));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id){service.delete(id);}}
